public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the starting and ending n-tersections are valid
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n || end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled";
    }

    // Check if the starting and ending n-tersections are connected
    if (!isConnected(start, end, paths)) {
        return "cannot be travelled";
    }

    // Check if the path between the starting and ending n-tersections is valid
    if (!isValidPath(start, end, paths)) {
        return "cannot be travelled";
    }

    return "can be travelled";
}

private static boolean isConnected(int[] start, int[] end, int[][] paths) {
    // Check if the starting and ending n-tersections are connected
    for (int[] path : paths) {
        if (path[0] == start[0] && path[1] == start[1] && path[2] == end[0] && path[3] == end[1]) {
            return true;
        }
    }
    return false;
}

private static boolean isValidPath(int[] start, int[] end, int[][] paths) {
    // Check if the path between the starting and ending n-tersections is valid
    for (int[] path : paths) {
        if (path[0] == start[0] && path[1] == start[1] && path[2] == end[0] && path[3] == end[1]) {
            return true;
        }
    }
    return false;
}

