public int search(int[] nums, int target) {
    int left = 0, right = nums.length - 1;
    while (left <= right) {
        int mid = left + (right - left) / 2;
        if (nums[mid] == target) {
            return mid;
        }
        if (nums[left] <= nums[mid]) {
            if (target < nums[mid] && target >= nums[left]) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        } else {
            if (target > nums[mid] && target <= nums[right]) {
                left = mid + 1;
            } else {
                right = mid - 1;
            }
        }
    }
    return -1;
}

public double trimMean(int[] arr) {
    // Calculate the mean of the array
    double mean = calculateMean(arr);

    // Calculate the number of elements to remove from the beginning and end of the array
    int numToRemove = (int) Math.ceil(arr.length * 0.05);

    // Create a new array with the elements removed from the beginning and end
    int[] trimmedArr = Arrays.copyOfRange(arr, numToRemove, arr.length - numToRemove);

    // Calculate the mean of the trimmed array
    double trimmedMean = calculateMean(trimmedArr);

    // Return the trimmed mean with an error within 10^-5
    return trimmedMean;
}

private double calculateMean(int[] arr) {
    // Calculate the sum of the elements in the array
    int sum = 0;
    for (int i = 0; i < arr.length; i++) {
        sum += arr[i];
    }

    // Calculate the mean of the array
    double mean = (double) sum / arr.length;

    // Return the mean
    return mean;
}

